        JsonElement Body(object value)=>JsonSerializer.SerializeToElement(value,Database.Compact);JsonElement Json(object value)=>Body(value);JsonElement Result(string value)=>JsonDocument.Parse(value).RootElement.Clone();
        var root=Path.GetFullPath(Path.Combine("test-results","community-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(root);
        User admin=new User{Id="a",Name="Admin",Role="Administrador"},student=new User{Id="us1",Role="Aluno",LinkedId="s1"},otherStudent=new User{Id="us2",Role="Aluno",LinkedId="s2"},instructor=new User{Id="ui1",Role="Instrutor",LinkedId="i1"},clerk=new User{Id="clerk",Role="Atendente",UnitId="u2"};
        string past=Operations.Now.AddDays(-1).ToString("s"),future=Operations.Now.AddDays(2).ToString("s");
        var state=new State{Units=[new(){Id="u1",Name="Escola teste"},new(){Id="u2",Name="Outra escola"}],Students=[new(){Id="s1",Name="Aluno teste",UnitId="u1",Cpf="CPF_PRIVADO_1",Notes="NOTA_INTERNA"},new(){Id="s2",Name="Outro aluno",UnitId="u2",Cpf="CPF_PRIVADO_2"}],Instructors=[new(){Id="i1",Name="Instrutor teste",UnitId="u1",Cpf="CPF_INSTRUTOR"},new(){Id="i2",Name="Outro instrutor",UnitId="u2"}],Enrollments=[new(){Id="e1",StudentId="s1",UnitId="u1",Category="B",LessonLimit=4}],Documents=[new(){Id="d1",StudentId="s1",Name="Contrato teste",Text="MEU DOCUMENTO"},new(){Id="d2",StudentId="s2",Name="Documento alheio",Text="SEGREDO ALHEIO"}],Entries=[new(){Id="p1",StudentId="s1",EnrollmentId="e1",Kind="Débito",Amount=100},new(){Id="p2",StudentId="s2",Kind="Débito",Amount=9999}],Lessons=[new(){Id="l1",StudentId="s1",EnrollmentId="e1",InstructorId="i1",UnitId="u1",Start=past,Status="Realizada"},new(){Id="l2",StudentId="s2",InstructorId="i2",UnitId="u2",Start=past,Status="Realizada"},new(){Id="l3",StudentId="s1",InstructorId="i1",UnitId="u1",Start=future},new(){Id="l4",StudentId="s2",InstructorId="i2",UnitId="u2",Start=future},new(){Id="l5",StudentId="s1",InstructorId="i1",UnitId="u1",Start=past},new(){Id="l6",StudentId="s1",InstructorId="i1",UnitId="u1",Start=future},new(){Id="excluded",StudentId="s1",InstructorId="i1",Start=past,ExcludedFromAgenda=true}]};
        File.WriteAllText(Path.Combine(root,"pilot.json"),JsonSerializer.Serialize(state,Store.Json));var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{["CFC_DATA_DIR"]=root}).Build();var env=new Env(root);var store=new Store(config,env);var resources=new StudentResources(store,config,env,DataProtectionProvider.Create(new DirectoryInfo(Path.Combine(root,"keys"))));var svc=new CommunityPortal(store,config,env,resources);
        var snapshot=Json(await svc.Snapshot(student));var raw=snapshot.GetRawText();Check(!raw.Contains("CPF_PRIVADO")&&!raw.Contains("NOTA_INTERNA")&&!raw.Contains("SEGREDO ALHEIO"),"Portal não expõe documentos, identificadores ou notas de terceiros");Check(snapshot.GetProperty("lessons").GetArrayLength()==4,"Aluno só vê próprias aulas sem duplicata excluída");Check(snapshot.GetProperty("finance").GetProperty("balance").GetDecimal()==100,"Financeiro isolado ao titular");Check(Json(await svc.Snapshot(instructor)).GetProperty("lessons").GetArrayLength()==4,"Instrutor só vê suas aulas");
