        var request=Body(new{type="Remarcar aula",message="Preciso de outro horário",lessonId="l3",owner="s2"});var op=Guid.NewGuid().ToString();var first=await svc.Request(student,request,op);Check(first==await svc.Request(student,request,op),"Reenvio não duplica solicitação");Check(Result(first).GetProperty("owner").GetString()=="s1","Titular da solicitação é decidido pelo servidor");await Reject(async()=>{await svc.Request(student,Body(new{type="Remarcar aula",message="Outra mensagem",lessonId="l3"}),op);},409,"Identificador não pode ser reutilizado em outro conteúdo");await Reject(async()=>{await svc.Request(student,Body(new{type="Remarcar aula",message="Mensagem válida",lessonId="l4"}),Guid.NewGuid().ToString());},403,"Aluno não solicita alteração de aula alheia");await Reject(()=>Task.Run(()=>svc.Inbox(student)),403,"Aluno não acessa fila da escola");
        var item=Result(first);await Reject(()=>Task.Run(()=>svc.Reply(student,item.GetProperty("id").GetString()!,Body(new{reply="resposta",status="Concluída",version=item.GetProperty("version").GetString()}),Guid.NewGuid().ToString())),403,"Aluno não responde como atendimento");await Reject(()=>Task.Run(()=>svc.Reply(clerk,item.GetProperty("id").GetString()!,Body(new{reply="resposta",status="Concluída",version=item.GetProperty("version").GetString()}),Guid.NewGuid().ToString())),403,"Atendente não responde outra unidade");var replyBody=Body(new{reply="Vamos combinar o novo horário",status="Em atendimento",version=item.GetProperty("version").GetString()});var replyOp=Guid.NewGuid().ToString();var reply=svc.Reply(admin,item.GetProperty("id").GetString()!,replyBody,replyOp);Check(reply==svc.Reply(admin,item.GetProperty("id").GetString()!,replyBody,replyOp),"Reenvio de resposta é idempotente");await Reject(()=>Task.Run(()=>svc.Reply(admin,item.GetProperty("id").GetString()!,replyBody,Guid.NewGuid().ToString())),409,"Resposta não sobrescreve atualização concorrente");Check(Json(await svc.Snapshot(student)).GetProperty("requests")[0].GetProperty("reply").GetString()=="Vamos combinar o novo horário","Aluno recebe a resposta da escola");Check(Json(await svc.Snapshot(otherStudent)).GetProperty("requests").GetArrayLength()==0,"Solicitações de outro aluno são isoladas");
        var confirm=Body(new{type="Confirmar presença",lessonId="l3"});var c1=await svc.Request(student,confirm,Guid.NewGuid().ToString());var c2=await svc.Request(student,confirm,Guid.NewGuid().ToString());Check(Result(c1).GetProperty("id").GetString()==Result(c2).GetProperty("id").GetString(),"Confirmação repetida gera um único registro");Check((await store.Read()).Lessons.Single(x=>x.Id=="l3").Status=="Agendada","Confirmar intenção não realiza nem valida aula");
        var skills=CommunityPortal.SkillNames.ToDictionary(x=>x,x=>3);var assessment=Body(new{skills,publicNote="Continue praticando as manobras",privateNote="NOTA_PRIVADA_INSTRUTOR",version=""});await svc.Assess(instructor,"l1",assessment,Guid.NewGuid().ToString());Check(!Json(await svc.Snapshot(student)).GetRawText().Contains("NOTA_PRIVADA_INSTRUTOR"),"Observação privada não chega ao aluno");Check(Json(await svc.Snapshot(student)).GetRawText().Contains("Continue praticando"),"Orientação pública aparece para o aluno");Check(Json(await svc.Snapshot(instructor)).GetRawText().Contains("NOTA_PRIVADA_INSTRUTOR"),"Instrutor pode rever sua observação privada");await Reject(async()=>{await svc.Assess(instructor,"l2",assessment,Guid.NewGuid().ToString());},403,"Avaliação de outro instrutor recusada");await Reject(async()=>{await svc.Assess(student,"l1",assessment,Guid.NewGuid().ToString());},403,"Aluno não se autoavalia como instrutor");await Reject(async()=>{await svc.Assess(instructor,"l3",assessment,Guid.NewGuid().ToString());},409,"Avaliação exige aula realizada");await Reject(async()=>{await svc.Assess(instructor,"l1",assessment,Guid.NewGuid().ToString());},409,"Avaliação antiga não sobrescreve versão nova");
        await svc.Attendance(instructor,"l5",Body(new{status="Realizada"}),Guid.NewGuid().ToString());var attendance=(await store.Read()).Lessons.Single(x=>x.Id=="l5");Check(attendance.Status=="Realizada"&&!attendance.Validated,"Realização interna não cria validação DETRAN");await Reject(async()=>{await svc.Attendance(instructor,"l4",Body(new{status="Falta"}),Guid.NewGuid().ToString());},403,"Presença de aula alheia recusada");await Reject(async()=>{await svc.Attendance(instructor,"l6",Body(new{status="Realizada"}),Guid.NewGuid().ToString());},400,"Aula futura não pode ser realizada");
        var bytes=Encoding.ASCII.GetBytes("%PDF-1.4\nARQUIVO FICTICIO\n%%EOF");var file=new FormFile(new MemoryStream(bytes),0,bytes.Length,"file","teste.pdf");var fileOp=Guid.NewGuid().ToString();var attachment=await svc.Upload(student,file,"Documento teste","Outro",fileOp);Check(attachment.StudentId=="s1","Arquivo enviado fica na própria ficha");Check((await svc.Upload(student,file,"Documento teste","Outro",fileOp)).Id==attachment.Id,"Reenvio de documento não duplica arquivo");Check((await resources.Read(student,attachment.Id)).Bytes.SequenceEqual(bytes),"Aluno pode baixar seu documento protegido");await Reject(async()=>{await resources.Read(otherStudent,attachment.Id);},403,"Outro aluno não baixa o documento");Check((await svc.Document(student,"d1")).Text=="MEU DOCUMENTO","Documento gerado disponível ao titular");await Reject(async()=>{await svc.Document(student,"d2");},404,"Documento gerado de terceiro não é acessível");
        await Reject(()=>Task.Run(()=>svc.Configure(student,Body(new CommunityPolicy()))),403,"Titular não altera permissões");svc.Configure(admin,Body(new CommunityPolicy{StudentRequests=false,StudentUploads=false,StudentFinance=false,InstructorAssessment=false,InstructorAttendance=false}));Check(Json(await svc.Snapshot(student)).GetProperty("finance").ValueKind==JsonValueKind.Null,"Administrador pode ocultar financeiro");await Reject(async()=>{await svc.Request(student,request,Guid.NewGuid().ToString());},403,"Política bloqueia novas solicitações");await Reject(async()=>{await svc.Upload(student,file,"Teste","Outro",Guid.NewGuid().ToString());},403,"Política bloqueia novos anexos");await Reject(async()=>{await svc.Assess(instructor,"l1",assessment,Guid.NewGuid().ToString());},403,"Política bloqueia avaliações");await Reject(async()=>{await svc.Attendance(instructor,"l5",Body(new{status="Falta"}),Guid.NewGuid().ToString());},403,"Política bloqueia realização/falta");Check(File.Exists(Path.Combine(root,"community.sqlite")),"Interações persistidas separadamente da importação original");
        var relationalRoot=Path.Combine(root,"relational");Directory.CreateDirectory(relationalRoot);using(var db=Database.Open(Path.Combine(relationalRoot,"fixture.sqlite")))
        {
            Database.Initialize(db);foreach(var property in typeof(State).GetProperties().Where(p=>p.PropertyType.IsGenericType&&p.PropertyType.GetGenericTypeDefinition()==typeof(List<>)))foreach(var entity in (System.Collections.IEnumerable)property.GetValue(state)!)Database.SaveEntity(db,property.Name,entity);
            foreach(var pair in new[]{("searchSchema","2"),("importId","community-fixture"),("policy",JsonSerializer.Serialize(state.Policy,Database.Compact))})Database.Execute(db,"INSERT INTO metadata VALUES($0,$1)",pair.Item1,pair.Item2);
        }
        File.WriteAllText(Path.Combine(relationalRoot,"active-database.json"),"{\"path\":\"fixture.sqlite\"}");var rc=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{["CFC_DATA_DIR"]=relationalRoot}).Build();var re=new Env(relationalRoot);var rs=new Store(rc,re);var rr=new StudentResources(rs,rc,re,DataProtectionProvider.Create(new DirectoryInfo(Path.Combine(relationalRoot,"keys"))));var relational=new CommunityPortal(rs,rc,re,rr);
        Check(Json(await relational.Snapshot(student)).GetProperty("lessons").GetArrayLength()==4,"Base relacional aplica o mesmo isolamento do aluno");
        Check(Json(await relational.Snapshot(instructor)).GetProperty("students").GetArrayLength()==1,"Base relacional limita alunos ao instrutor");
        Check(!(await rs.Community("Aluno","s1")).Users.Any(),"Consulta do portal não carrega credenciais da equipe");
        Check(Json(await relational.Snapshot(student)).GetProperty("finance").GetProperty("balance").GetDecimal()==100,"Financeiro usa os registros importados da ficha");
        Console.WriteLine($"{passed} verificações dos portais passaram.");
